        if dok and data and data.data then
            local list = {}
            for _, s in ipairs(data.data) do
                if s.id ~= game.JobId and (s.playing or 0) < (s.maxPlayers or 0) then list[#list + 1] = s.id end
            end
            if #list > 0 then
                pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, list[math.random(1, #list)], lp) end)
                return
            end
        end
    end
    pcall(function() TeleportService:Teleport(game.PlaceId, lp) end)
end
do
    local hm = hookmetamethod
    local gnm = getnamecallmethod
    if hm and gnm then
        local old
        local ok = pcall(function()
            old = hm(game, "__namecall", (newcclosure or function(f) return f end)(function(self, ...)
                if RUNNING then
                    local m = gnm()
                    if m == "Kick" and self == lp and on("g_antikick") and not (checkcaller and checkcaller()) then return nil end
                    if m == "FireServer" and self == EB and on("g_antiidle") then
                        local a = ...
                        if a == "AfkReconnectRequest" then return nil end
                    end
                end
                return old(self, ...)
            end))
        end)
        if not ok then old = nil end
    end
end
