local function loop(interval, fn)
    task.spawn(function()
        while RUNNING do
            local ok, err = pcall(fn)
            if not ok then S.lastErr = tostring(err) end
            task.wait(type(interval) == "function" and interval() or interval)
        end
    end)
end
