    if r.claimAt and t - r.claimAt < 0.6 then return end
    if r.wait and t - r.sentAt < 3.5 then return end
    if t - r.gotAt < 3.05 or t - r.sentAt < 3.05 then return end
    r.wait = true; r.sentAt = t
    cmd("RollAnt", { Source = "ProximityPrompt" })
end)
