local function antLevelCost(m)
    local price = tonumber(m:GetAttribute("Price")) or 0
    local lvl = math.max(tonumber(m:GetAttribute("Level")) or 1, 1)
    return math.floor(price * 0.05 * 1.35 ^ (lvl - 1))
end
loop(2, function()
    if on("f_slot") then
        local layer = tonumber(lp:GetAttribute("NestLayer")) or 0
        if not (S.slotMax and S.slotMax == layer) then
            S.slotMax = false
            local row = CFG.nest[D.slots]
            local price = row and tonumber(row.Price)
            if price and spendFree() >= price then
                spend(price)
                cmd("AddAntSlot", { Source = "ProximityPrompt", RoomIndex = D.room, SlotIndex = D.slots + 1 })
                task.wait(1)
            end
        end
    end
    if on("f_upant") then
        local ants = myAnts()
        table.sort(ants, function(a, b) return antLevelCost(a) < antLevelCost(b) end)
        for _, m in ipairs(ants) do
            if not on("f_upant") then break end
            local cost = antLevelCost(m)
            if cost <= 0 or spendFree() < cost then break end
            spend(cost)
            cmd("UpgradeEquippedAnt", { Source = "RoomAntInfoGui", AntIndex = tonumber(m:GetAttribute("AntIndex")) })
            task.wait(0.3)
        end
    end
end)
loop(1, function()
    if not on("s_sell") then return end
    if clock() - S.priceAt > 4 then cmd("RequestSellFoodPrice", { Source = "SellShopModel", UserId = lp.UserId }) end
    if clock() - (S.bmAskAt or 0) > 30 then S.bmAskAt = clock(); ev("BlackMarketSnapshotRequest", {}) end
    local n = math.floor(D.food - foodKeep())
    if n <= 0 then return end
    if on("s_bm") and bmOpen() then
        local part = bmSellPart()
        if part and clock() - (S.bmSoldAt or 0) > 5 then
            S.bmSoldAt = clock()
            withTp(function()
                tp(part.Position)
                task.wait(0.35)
                cmd("SellPlayerFood", { FoodAmount = n, Source = "BlackMarket" })
                task.wait(0.6)
            end)
        end
