    for _, n in ipairs({ "Client_Assets", "EquippedPets", "PlacedPetEggs" }) do local f = Workspace:FindFirstChild(n); if f then ex[#ex + 1] = f end end
    if lp.Character then ex[#ex + 1] = lp.Character end
