    local off = Vector3.new((math.random() - 0.5) * pm.Size.X * 0.6, 0, (math.random() - 0.5) * pm.Size.Z * 0.6)
    local p = pm.CFrame:PointToWorldSpace(off)
    local hit = Workspace:Raycast(p + Vector3.new(0, 25, 0), Vector3.new(0, -80, 0), params)
    if hit and hit.Normal.Y >= 0.55 then return hit end
    return nil
