local FX = { on = false, saved = setmetatable({}, { __mode = "k" }), conns = {} }
local FX_CLASS = { ParticleEmitter = true, Beam = true, Trail = true, Fire = true, Smoke = true, Sparkles = true }
FX.watched = setmetatable({}, { __mode = "k" })
local function fxOff(d)
    if not FX_CLASS[d.ClassName] then return end
    if d.Enabled and FX.saved[d] == nil then
        FX.saved[d] = true
        pcall(function() d.Enabled = false end)
    end
    if not FX.watched[d] then
        FX.watched[d] = d:GetPropertyChangedSignal("Enabled"):Connect(function()
            if FX.on and d.Enabled then FX.saved[d] = true; d.Enabled = false end
        end)
    end
end
local function setFx(want)
    if want == FX.on then return end
    FX.on = want
    if want then
        task.spawn(function()
            local n = 0
            for _, d in ipairs(Workspace:GetDescendants()) do
                if not FX.on then return end
                fxOff(d)
                n = n + 1; if n % 600 == 0 then task.wait() end
            end
        end)
        FX.conns[#FX.conns + 1] = Workspace.DescendantAdded:Connect(function(d)
            if FX.on and FX_CLASS[d.ClassName] then task.defer(fxOff, d) end
        end)
        for _, e in ipairs(game:GetService("Lighting"):GetChildren()) do
            if (e:IsA("BloomEffect") or e:IsA("SunRaysEffect") or e:IsA("BlurEffect") or e:IsA("DepthOfFieldEffect")) and e.Enabled then FX.saved[e] = true; e.Enabled = false end
        end
    else
        for _, c in ipairs(FX.conns) do pcall(function() c:Disconnect() end) end
        FX.conns = {}
        for _, c in pairs(FX.watched) do if typeof(c) == "RBXScriptConnection" then pcall(function() c:Disconnect() end) end end
        FX.watched = setmetatable({}, { __mode = "k" })
        for d in pairs(FX.saved) do pcall(function() if d.Parent then d.Enabled = true end end) end
        FX.saved = setmetatable({}, { __mode = "k" })
    end
end
onClean(function() setFx(false) end)
local GSET = { applied = {}, orig = {} }
local GSET_LIST = { { t = "g_others", key = "ShowOtherAnts", want = false }, { t = "g_lowgfx", key = "LowPerformance", want = true } }
local function gameSetting(key, value)
    return gcall(function()
        local h = ReplicatedStorage:FindFirstChild("Helper"); h = h and h:FindFirstChild("PlayerSettingHelper")
        if not h then return nil end
        local ok, m = pcall(require, h)
        if not (ok and m) then return nil end
        local cur = m.GetLocalSettings and m.GetLocalSettings()
        local before = type(cur) == "table" and cur[key]
        if value ~= nil and m.SetLocalSetting then pcall(m.SetLocalSetting, key, value) end
        return before
    end)
end
loop(1, function()
    for _, g in ipairs(GSET_LIST) do
        local want = on(g.t) == true
        if want and not GSET.applied[g.t] then
            local before = gameSetting(g.key, g.want)
            if GSET.orig[g.key] == nil then GSET.orig[g.key] = before end
            GSET.applied[g.t] = true
        elseif not want and GSET.applied[g.t] then
            local o = GSET.orig[g.key]
            if o == nil then o = not g.want end
            gameSetting(g.key, o)
            GSET.applied[g.t] = nil
        end
    end
end)
onClean(function()
    for _, g in ipairs(GSET_LIST) do
        if GSET.applied[g.t] then local o = GSET.orig[g.key]; if o == nil then o = not g.want end; gameSetting(g.key, o) end
    end
end)
local POPUPS = { "AwardReward", "DungeonEggRewardGui" }
local popSaved = {}
loop(0.5, function()
    setFx(on("g_fx") == true)
    local pg = lp:FindFirstChild("PlayerGui"); if not pg then return end
    local hud = pg:FindFirstChild("HUDContainer")
    local ef = hud and hud:FindFirstChild("EffectFrame")
    if ef and ef:IsA("GuiObject") then
        if on("g_fx") then
            if ef.Visible then FX.hud = ef; ef.Visible = false end
        elseif FX.hud then
            pcall(function() FX.hud.Visible = true end); FX.hud = nil
        end
    end
    if on("g_popups") then
        for _, n in ipairs(POPUPS) do
            local g = pg:FindFirstChild(n)
            if g and g:IsA("ScreenGui") and g.Enabled then popSaved[g] = true; g.Enabled = false end
        end
    elseif next(popSaved) then
        for g in pairs(popSaved) do pcall(function() g.Enabled = true end) end
        popSaved = {}
    end
end)
onClean(function()
    for g in pairs(popSaved) do pcall(function() g.Enabled = true end) end
    if FX.hud then pcall(function() FX.hud.Visible = true end) end
end)
local CLAIMED = {}
loop(5, function()
    if not on("r_all") then return end
    if clock() - (CLAIMED.online or -1e9) < 60 then return end
    CLAIMED.online = clock()
    local n = 0
    action("/功能商人/在线奖励领取?购买", "__null__", "__null__", "__null__")
    if clock() - (CLAIMED.daily or -1e9) > 300 then
        CLAIMED.daily = clock()
        action("/功能商人/七日奖励领取?购买", "__null__", "__null__", "__null__")
        action("/活动/群组奖励/群组每日奖励?购买")
        local okA, ad = pcall(function() return HttpService:JSONDecode(lp:GetAttribute("ActivityData") or "{}") end)
        if okA and type(ad) == "table" then
            local login, got = tonumber(ad.LoginMask) or 0, tonumber(ad.RewardMask) or 0
            for day = 1, 14 do
                local bit = 2 ^ (day - 1)
                if math.floor(login / bit) % 2 == 1 and math.floor(got / bit) % 2 == 0 then
                    action("/功能商人/活动签到?购买", "__null__", "__null__", { DayId = day })
                    n = n + 1
                end
            end
        end
        local PROG = { AntCollectReward = "蚂蚁图鉴奖励进度", MutationCollectReward = "突变图鉴奖励进度" }
        for cid, prop in pairs(PROG) do
            local row = CFG.index[cid]
            local done = math.max(math.floor(tonumber(query("/属性/" .. prop .. "?属性数量")) or 0), 0)
            local tier = type(row) == "table" and type(row.Content) == "table" and row.Content[done + 1]
            if tier then
                action("/图鉴系统/领取图鉴奖励?购买", "__null__", "__null__", { HttpService:JSONEncode({ ConfigId = row.Id or cid, Level = tier.Level }) })
                task.wait(0.2)
            end
        end
        if clock() - (CLAIMED.ride or -1e9) > 600 then CLAIMED.ride = clock(); for i = 1, #CFG.ride do action("/功能商人/骑乘单位进度奖励领取?购买", "__null__", "__null__", { i }); task.wait(0.1) end end
    end
    setText(UI.rew, L["Last check "] .. os.date("%H:%M"))
end)
loop(1, function()
    local s = S.stats
    setText(UI.roll, string.format(L["Rolled %d · Bought %d"], s.rolled, s.bought))
    local pct = pricePct()
    local p = S.price
    if bmOpen() then setText(UI.price, L["Black Market open"])
    elseif p and pct then setText(UI.price, string.format(L["Price %.2f · %d%%"], tonumber(p.GoldPerFood) or 0, math.floor(pct)))
    else setText(UI.price, L["Price: waiting"]) end
    setText(UI.money, string.format(L["Cash %s · Food %s"], fmt(D.gold), fmt(D.food)))
    local mins = math.floor((clock() - s.started) / 60)
    local line = string.format("%dm · Sold %s · +%s cash\nBought %d ants · %d kills", mins, fmt(s.sold), fmt(s.earned), s.bought, s.kills)
    if S.msg ~= "" then line = line .. "\n" .. S.msg end
    setText(UI.sum, line)
end)
loop(30, function()
    local url = tostring(val("g_hook", ""))
    if not url:find("^https://discord") then return end
    if clock() - (S.hookAt or 0) < val("g_hookmin", 30) * 60 then return end
    S.hookAt = clock()
    local req = request or (syn and syn.request) or http_request
    if not req then return end
    local s = S.stats
    local msg = string.format("**%s** · %dm\nCash %s · Food %s\nSold %s food for %s\nBought %d ants (%s) · Rolled %d\nDungeon kills %d · Time coins %d · Gear %d",
        lp.Name, math.floor((clock() - s.started) / 60), fmt(D.gold), fmt(D.food), fmt(s.sold), fmt(s.earned), s.bought, fmt(s.spent), s.rolled, s.kills, s.coins, s.gear)
    pcall(req, { Url = url, Method = "POST", Headers = { ["Content-Type"] = "application/json" }, Body = HttpService:JSONEncode({ content = msg }) })
end)
local FLY = { bv = nil, bg = nil }
local function stopFly()
    if FLY.bv then pcall(function() FLY.bv:Destroy() end) end
    if FLY.bg then pcall(function() FLY.bg:Destroy() end) end
    FLY.bv, FLY.bg = nil, nil
end
onClean(stopFly)
track(RunService.Heartbeat:Connect(function()
    if not RUNNING then return end
    local c = lp.Character
    local hum = c and c:FindFirstChildOfClass("Humanoid")
    local r = hrp()
    if hum and on("p_speed") then hum.WalkSpeed = val("p_speedv", 40) end
    if on("p_fly") and r and hum then
        if not FLY.bv or FLY.bv.Parent ~= r then
            stopFly()
            FLY.bv = Instance.new("BodyVelocity"); FLY.bv.MaxForce = Vector3.new(1e9, 1e9, 1e9); FLY.bv.Velocity = Vector3.zero; FLY.bv.Parent = r
            FLY.bg = Instance.new("BodyGyro"); FLY.bg.MaxTorque = Vector3.new(1e9, 1e9, 1e9); FLY.bg.P = 9e4; FLY.bg.Parent = r
        end
        local cam = Workspace.CurrentCamera
        local dir = hum.MoveDirection
        local up = (UserInputService:IsKeyDown(Enum.KeyCode.Space) and 1 or 0) - (UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) and 1 or 0)
        local look = cam.CFrame.LookVector
        local v = dir * val("p_flyv", 60)
        if dir.Magnitude > 0 then v = v + Vector3.new(0, look.Y * dir.Magnitude * val("p_flyv", 60), 0) end
        FLY.bv.Velocity = v + Vector3.new(0, up * val("p_flyv", 60), 0)
        FLY.bg.CFrame = cam.CFrame
    elseif FLY.bv then stopFly() end
end))
track(RunService.Stepped:Connect(function()
    if not (RUNNING and (on("p_noclip") or on("p_fly"))) then return end
    local c = lp.Character
    if c then for _, p in ipairs(c:GetDescendants()) do if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end end end
end))
track(UserInputService.JumpRequest:Connect(function()
    if not on("p_jump") then return end
    local c = lp.Character
    local hum = c and c:FindFirstChildOfClass("Humanoid")
    if hum then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
end))
track(game:GetService("ProximityPromptService").PromptButtonHoldBegan:Connect(function(p)
    if on("p_prompt") and fireproximityprompt then pcall(fireproximityprompt, p) end
end))
track(lp.Idled:Connect(function()
    if on("g_antiidle") then pcall(function() VirtualUser:CaptureController(); VirtualUser:ClickButton2(Vector2.new()) end) end
end))
local function staffCheck(p)
    if not (on("g_staff") and p and STAFF[p.UserId]) then return end
    local what = val("g_staffdo", "Notify")
    notify(L["Staff joined: "] .. p.Name)
    if what == "Hop Server" then hopServer() elseif what == "Leave" then lp:Kick("Staff joined") end
end
track(Players.PlayerAdded:Connect(staffCheck))
task.delay(3, function() for _, p in ipairs(Players:GetPlayers()) do staffCheck(p) end end)
